def reserve(%__MODULE__{} = stock, name) do
    count = portions(name)
    cond do
      count == 0 -> {:error, :unknown}
      remaining(stock, name) < count -> {:error, :sold_out}
      true -> {:ok, %{stock | beans: Map.update!(stock.beans, name, &(&1 - count))}}
    end
  end

